/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        _isShowScatter:false
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._super()
    },

    start () {

    },

    //旋转
    StartMove:function(){
        this._super()
        this._isShowScatter = false
    },

    ShowAntiEffect:function(bShow,name){
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode,this.node)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }
                        
                    }
                }
            }
        }else{
            let node = cc.find(name,this.node)
            if(node){
                node.active = bShow
            }
            else{
                cc.log("未找到加速节点：mask/node_anti");
            }
        }
    },

    //重写
    StartRecycleSymbol:function(){
        //此游戏没用到回收卷轴的功能，免费游戏和普通游戏分别配置了一个row，调用此接口反而会导致免费游戏卷轴被错误回收
        //故此注销这个接口的调用
        // let cfg = cc.vv.gameData.getGameCfg()
        // if(this._symbols.length > (cfg.row+1)){
        //     let nCount = -(this._symbols.length -(cfg.row+1))
        //     this.AddCount(nCount)
        // }
    },

    //列停止
    OnReelSpinEnd:function(){
        this._reelState = []
        let slots = cc.vv.gameData.GetSlotsScript()
        slots.OnReelSpinEnd(this._reelIdx)

        let mapInfo = cc.vv.gameData.getMapInfo()
        if(this._cfg.MapConfig[mapInfo.currId].type > 3){
            for (let i = 0; i < this._symbols.length; i++) {
                const symbol = this._symbols[i];
                if(symbol._id === 1){  //wild
                    let idx = (this._reelIdx + 1) + (this._cfg.row_free - i - 1) * this._cfg.col_free
                    cc.vv.gameData.GetSlotsScript().showStopWild(idx,symbol)
                }
            }
        }

        //不能判断，停下来的列等于总共的列，因为有时候只旋转了3列
        //停下来的列以及等于最后一列旋转的列，
        //说明整个列已经停止
        let lastReelStopIdx = slots.GetLastStopReelIdx()
        if(this._reelIdx == lastReelStopIdx){
            //所有列都停止了
            slots.OnSpinEnd()
        }
    },

    // update (dt) {},
});
