
cc.Class({
    extends: cc.Component,

    properties: {
        chuan:{
            default:null,
            type:cc.Node
        },
        qiepin1:{
            default:null,
            type:cc.Node
        },
        qiepin2:{
            default:null,
            type:cc.Node
        },
        map:{
            default:null,
            type:cc.Node
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showChuan(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_free)
            this.chuan.active = true

            this.chuan.opacity = 0;
            cc.tween(this.chuan).to(0.3, {opacity:255}).start();
            let spine = cc.find("yase", this.chuan);
            spine.getComponent(sp.Skeleton).setAnimation(0,"skill", false);
            spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine.getComponent(sp.Skeleton).setCompleteListener(null)
                cc.tween(this.chuan).to(0.3, {opacity:0}).start();
                this.chuan.active = false
                sucess()
            })

            await this.awaitTime(2)
            if(callBack){
                callBack()
            }
        });
    },

    showQiePing1(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_wheel)
            this.qiepin1.active = true
            let show_popupSp = this.qiepin1.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation",false)
            show_popupSp.setCompleteListener(()=>{
                this.qiepin1.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            this._showQiePing2()
            await this.awaitTime(0.5)
            if(callBack){
                callBack()
            }
        });
    },

    _showQiePing2(){
        return new Promise(async (sucess, failed)=>{
            this.qiepin2.active = true
            let show_popupSp = this.qiepin2.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation",false)
            show_popupSp.setCompleteListener(()=>{
                this.qiepin2.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
        });
    },

    showMap(callBack){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition_mapfree)
            this.map.active = true
            let show_popupSp = this.map.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation",false)
            show_popupSp.setCompleteListener(()=>{
                this.map.active = false
                sucess()
                show_popupSp.setCompleteListener(null)
            })
            await this.awaitTime(3)
            if(callBack){
                callBack()
            }
        });
    },

    // update (dt) {},
});
