/**
 * 墨西哥帅哥，奖池
 */
let jackpotNames = ['Mini','Minor','Major','Grand']  //节点名称
cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {
        _nowUpdatePool:0,  //当前更新的pool节点
    },

    
    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        let jpNodeName = jackpotNames[poolType]
        this.updataJackPoolLock(poolType,bLock)
        if(jpNodeName){
            let safeNode = cc.find('Canvas/safe_node')
            let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
            if(jpNode){
                let targetJpNode = cc.find('prizePool_'+jpNodeName,jpNode.node.parent)
                if(targetJpNode){
                    let lbl_num = cc.find("lbl_num",targetJpNode)
                    let bg = cc.find("bg", targetJpNode);
                    // let title = cc.find("title",targetJpNode)
                    // let liuguang = cc.find("liuguang",targetJpNode)
                    // let winEffect = cc.find("winEffect",targetJpNode)
                    if(bLock){
                        if(!bInit){
                            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_lock)
                            // winEffect.active = true
                            // let winEffectSp = winEffect.getComponent(sp.Skeleton)
                            // winEffectSp.setAnimation(0,"animation"+(4 - poolType)+"_2",false)
                            // winEffectSp.setCompleteListener(()=>{
                            //     winEffectSp.setCompleteListener(null)
                            //     winEffect.active = false
                            // })
                        }
                        lbl_num.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme219_4")
                        // title.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base").getSpriteFrame("theme219_base_jp_name"+(4 - poolType)+"_0")
                        // targetJpNode.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base").getSpriteFrame("theme219_base_jp_bg"+(4 - poolType)+"_0")
                        Global.showSpriteGray(bg, true);
                        // liuguang.active = false
                    }
                    else{
                        if(!bInit){
                            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jp_unlock)
                            // winEffect.active = true
                            // let winEffectSp = winEffect.getComponent(sp.Skeleton)
                            // winEffectSp.setAnimation(0,"animation"+(4 - poolType),false)
                            // winEffectSp.setCompleteListener(()=>{
                            //     winEffectSp.setCompleteListener(null)
                            //     winEffect.active = false
                            // })
                        }
                        lbl_num.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme219_3")
                        // title.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base").getSpriteFrame("theme219_base_jp_name"+(4 - poolType))
                        // targetJpNode.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base").getSpriteFrame("theme219_base_jp_bg"+(4 - poolType))
                        Global.showSpriteGray(bg, false);
                        // liuguang.active = true
                    }
                }
            }
        }
    },

    updataJackPoolLock(index,isLock){
        let tempIndex = index
        if(isLock){
            if(this._nowUpdatePool < tempIndex){
                return
            }
            this._nowUpdatePool = tempIndex
        }else{
            if(this._nowUpdatePool > tempIndex){
                return
            }
            this._nowUpdatePool = tempIndex
        }
        let safeNode = cc.find('Canvas/safe_node')
        let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
        if(jpNode){
            for (let i = 0; i < jackpotNames.length; i++) {
                const jpNodeName = jackpotNames[i];
                let tips = cc.find('tips_'+jpNodeName,jpNode.node.parent)
                if(tips){
                    if(index === i){
                        if(isLock){
                            cc.find("lock",tips).active = true
                            cc.find("unlock",tips).active = false
                            tips.scale = 0
                            cc.tween(tips)
                            .to(0.5,{scale:1},{easing:"backOut"})
                            .delay(0.5)
                            .to(0.5,{scale:0},{easing:"backIn"}).start()
                        }
                        else{
                            cc.find("lock",tips).active = false
                            cc.find("unlock",tips).active = true
                            tips.scale = 0
                            cc.tween(tips)
                            .to(0.5,{scale:1},{easing:"backOut"})
                            .delay(0.5)
                            .to(0.5,{scale:0},{easing:"backIn"}).start()
                        }
                    }else{
                        tips.stopAllActions()
                        tips.scale = 0
                    }
                }
            }
        }
    },
    // update (dt) {},
});
