let multList = {10:0,8:1,7:2,6:3,5:4,4:5,3:6,2:7}
cc.Class({
    extends: cc.Component,

    properties: {
        spin:{
            default:null,
            type:cc.Node
        },
        selectEffect:{
            default:null,
            type:cc.Node
        },
        guang:{
            default:null,
            type:cc.Node
        },
        rollNode:{
            default:null,
            type:cc.Node
        },
        _mult:0,
        _sucess:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this.spin.on("click",this.onSpin,this)
    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showWheel(position,mult,sucess){
        this._mult = mult
        this._sucess = sucess
        this.node.active = true
        if(position){
            this.node.position = position
        }
        this.node.scale = 1
        this.rollNode.angle = 0
        this.guang.active = true
        let guangSp = this.guang.getComponent(sp.Skeleton)
        guangSp.setAnimation(0,"animation2",false)
        guangSp.setCompleteListener(()=>{
            this.guang.active = false
            guangSp.setCompleteListener(null)
        })
        this.selectEffect.active = false
        cc.tween(this.spin).repeatForever(cc.tween().to(0.7,{scale:1.3}).to(0.7,{scale:1})).start()
        this.spin.getComponent(cc.Button).interactable = true
        cc.vv.gameData.checkAutoPlay(this.spin, this.onSpin.bind(this));
    },

    onSpin(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.smallwheel_click)
        this.spin.stopAllActions();
        this.spin.getComponent(cc.Button).interactable = false
        this.spin.stopAllActions()
        this.guang.active = false
        this.onSpinWheel(multList[this._mult])
    },

    onSpinWheel(index){
        let rusltAngle = -45 * index
        rusltAngle -= 360*5
        this.selectEffect.active = false
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.smallwheel_roll)
        cc.tween(this.rollNode).to(6,{angle:rusltAngle - 20},{easing:"quadInOut"}).to(0.7,{angle:rusltAngle},{easing:"quadIn"}).call(async ()=>{
            this.rollNode.angle %= 360
            this.selectEffect.active = true
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.smallwheel_option)
            await this.awaitTime(2)
            this.hide()
        }).start()
    },

    hide(){
        cc.tween(this.node).to(0.3,{scale:0}).call(()=>{
            this.node.active = false
            if(this._sucess){
                this._sucess()
            }
        }).start()
    },

    // update (dt) {},
});
