    showWin(){
        this.node.active = true
        let popBg = cc.find("popup",this.node)
        popBg.opacity = 0
        cc.tween(popBg).to(0.3,{opacity:255}).start()
    },

    hideWin(callBack){
        let popBg = cc.find("popup",this.node)
        cc.tween(popBg).to(0.3,{opacity:0}).call(()=>{
            if(callBack){
                callBack()
            }
            this.node.active = false
        }).start()
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //显示免费游戏赢金币
    showFreeGameWinCoin(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.free_dialog_collect_show)
            this.showWin()
            this.freeCollectButton.active = false
            this.freeWinCoin.active = false
            let show_popup = cc.find("freeGameWinCoin",this.node)
            show_popup.active = true;
            let show_popupSp = show_popup.getComponent(sp.Skeleton)
            show_popupSp.setAnimation(0,"animation1_1",false)
            show_popupSp.addAnimation(0,"animation1_2",true)
            await this.awaitTime(0.5)
            this.freeCollectButton.active = true
            this.freeWinCoin.active = true
            this._startAddCoin = true
            Global.doRoallNumEff(this.freeWinCoin,Math.floor(num*0.1),num,2.5,()=>{
                this._startAddCoin = false
            },null,0,true);

            let self = this;
            let collectFunc = function () {
                return new Promise(async (success1) => {
                    self.freeCollectButton.getComponent(cc.Button).interactable = false
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click)
                    if(self._startAddCoin){
                        self._startAddCoin = false
                        self.freeWinCoin.stopAllActions()
                        let winCoinLabel = self.freeWinCoin.getComponent(cc.Label)
                        winCoinLabel.string = Global.FormatNumToComma(num)
                    }
                    await self.awaitTime(0.2)
                    show_popupSp.setAnimation(0,"animation1_3",false)
                    show_popupSp.setCompleteListener(()=>{
                        show_popup.active = false
                        self.hideWin(()=>{
                            sucess()
                        })
                        show_popupSp.setCompleteListener(null)
                    })
                    await self.awaitTime(0.5)
                    self.freeCollectButton.active = false
                    self.freeWinCoin.active = false
                    success1()
                })
            }
            cc.vv.gameData.checkAutoPlay(this.freeCollectButton, collectFunc);
            this.freeCollectButton.getComponent(cc.Button).interactable = true
            this.freeCollectButton.off("click");
            this.freeCollectButton.on("click", async ()=>{
                this.freeCollectButton.stopAllActions()
                collectFunc()
            });
        });
    },

