/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //重写
    SetSymbolIdx:function(idx){
        this._symbolIdx = idx;
        if(this._id === 2){
            this.node.zIndex = 150 - idx;
        }else{
            this.node.zIndex = 100 - idx;
        }
    },

    //重写
    //停止动画
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            this.OnReelBounsAction(aniNode)
            
            if(cfg.symbol[id].stop_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                }
            }
        }
    },

    changeWild(){
        this.setAnimationToTop(false)
        this.ShowById(1)
    },

    OnReelBounsAction:function(node){
        let cfg = cc.vv.gameData.getGameCfg()
        let distance = cfg.bounceInfo ? cfg.bounceInfo.distance : 30
        let time = cfg.bounceInfo ? cfg.bounceInfo.time : 0.3
        //考虑到倍率问题
        time = time/cc.vv.gameData.GetSlotsScript().GetTimeScale() 
        
        cc.tween(node)
        .to(time,{position:cc.v2(node.x,node.y + distance)})
        .start()
    },

    //显示随机符号
    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let reel = cc.vv.gameData.GetSlotsScript()._reels[this._reelIdx]
        if(cc.vv.gameData.GetSlotsScript()._isInFree){
            reel = cc.vv.gameData.GetSlotsScript()._reelsFree[this._reelIdx]
        }
        if(reel._isShowScatter){
            let randIdx = Global.random(2,cfg.randomSymbols.length)
            let randVal = cfg.randomSymbols[randIdx-1]
            this.ShowById(randVal)
        }else{
            let randIdx = Global.random(1,cfg.randomSymbols.length)
            let randVal = cfg.randomSymbols[randIdx-1]
            if(randVal === 2){
                reel._isShowScatter = true
            }
            this.ShowById(randVal)
        }


    },

    // update (dt) {},
});
