let speed = 1540
let g = 570
cc.Class({
    extends: cc.Component,

    properties: {
        spin:{
            default:null,
            type:cc.Node
        },
        anniuEffect:{
            default:null,
            type:cc.Node
        },
        huoxing:{
            default:null,
            type:cc.Node
        },
        zhongjiang:{
            default:null,
            type:cc.Node
        },
        rollNode:{
            default:null,
            type:cc.Node
        },
        _rollNodeList:[],    //滚动节点列表
        _startMove:false,
        _trueSpeed:0,
        _startStop:false,
        _readStop:false,
        _resultNode:null,
        _sucess:null,
        _resultData:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this.spin.on("click",this.onSpin,this)
        for (let i = 15; i >= 0; i--) {
            this._rollNodeList[this._rollNodeList.length] = cc.find("node"+i,this.rollNode)
        }
    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showWheel(){
        return new Promise(async(sucess,failed)=>{
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.wheel_bgm)
            cc.vv.gameData.getManage().stopCasualAnimation()
            this._sucess = sucess
            this.node.active = true
            cc.find("Canvas/safe_node/character").active = false;
            let anniuSp = this.anniuEffect.getComponent(sp.Skeleton)
            anniuSp.setAnimation(0,"animation",true)
            this.huoxing.active = false
            this.zhongjiang.active = false
            this.spin.getComponent(cc.Button).interactable = true
            cc.vv.gameData.checkAutoPlay(this.spin, this.onSpin.bind(this));
        })
    },

    onSpin(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_click)
        this.spin.stopAllActions();
        this.spin.getComponent(cc.Button).interactable = false
        let anniuSp = this.anniuEffect.getComponent(sp.Skeleton)
        anniuSp.setAnimation(0,"animation2",false)
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 2;
        cc.vv.NetManager.send(req);
    },

    async onSpinWheel(data){
        this._resultData = data
        this._startMove = true
        this._trueSpeed = 0
        this._startStop = false
        this.zhongjiang.active = false
        this.huoxing.active = true
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_roll)
        await this.awaitTime(3.5)
        this._readStop = true
        if(data.itemId){
            this._resultNode = cc.find("node"+(data.itemId-1),this.rollNode)
        }
    },

    async endSpin(){
        Global.SlotsSoundMgr.stopBgm()
        if(this._resultData.freeInfo){
            await cc.vv.gameData.getPopWinManage().showFreeGameTimes(this._resultData.freeInfo.freeCnt)
            cc.vv.gameData.AddTotalFreeTime(this._resultData.freeInfo.freeCnt)
            await cc.vv.gameData.getQiePing().showChuan(()=>{
                cc.vv.gameData.GetSlotsScript().showFreeGameSlots()
                this.hide()
            })
            cc.vv.gameData.GetSlotsScript().ShowFreeGame(true)
        }
        if(this._resultData.jackpot){
            if(cc.vv.gameData.GetSlotsScript().getPoolIsLocked(this._resultData.jackpot.id)){
                await cc.vv.gameData.getPopWinManage().showFreeGameWinCoin(this._resultData.jackpot.value)
            }else{
                await cc.vv.gameData.getPopWinManage().showJackpotWinCoin(this._resultData.jackpot.value,this._resultData.jackpot.id)
            }
            await cc.vv.gameData.getQiePing().showQiePing1(()=>{
                this.hide()
                cc.find("Canvas/safe_node/character").active = true;
                cc.vv.gameData.GetSlotsScript().hideWinJackPoolAnimation(this._resultData.jackpot.id)
            })
            let nTotal = this._resultData.jackpot.value + cc.vv.gameData.GetBottomScript().getCurrentWin()
            cc.vv.gameData.AddCoin(this._resultData.jackpot.value)
            await cc.vv.gameData.GetSlotsScript().ShowWinCoin(this._resultData.jackpot.value,nTotal,true)
            Global.SlotsSoundMgr.playNormalBgm(true)
        }
        this.exitWheel()
    },

    startWheel(length){
        for (let i = 0; i < this._rollNodeList.length; i++) {
            const element = this._rollNodeList[i];
            element.y -= length
        }
        let halfHeight = this.rollNode.height * 0.5
        let firstNode = this._rollNodeList[0]
        if(firstNode.y <= -halfHeight - firstNode.height * 0.5){  //向下移出了裁剪区
            let changeNode = this._rollNodeList.shift()
            let lastNode = this._rollNodeList[this._rollNodeList.length - 1]
            changeNode.y = lastNode.y + lastNode.height * 0.5 + changeNode.height * 0.5
            this._rollNodeList.push(changeNode)
        }
        if(this._readStop){
            if(this._resultNode){
                let pos = Math.abs(this._resultNode.y) - 6
                if(pos < 20){
                    this._startStop = true
                    this._startMove = false
                    this._readStop = false
                }
            }
        }
    },

    hide(){
        Global.SlotsSoundMgr.stopBgm()
        cc.vv.gameData.getManage().resumeCasualAnimation()
        this.node.active = false
    },

    exitWheel(){
        if(this._sucess){
            this._sucess()
            this._sucess = null
        }
    },

    update (dt) {
        if(this._startMove){
            this._trueSpeed += dt*g
            if(this._trueSpeed > speed){
                this._trueSpeed = speed
            }
            this.startWheel(dt*this._trueSpeed)
        }
        if(this._startStop){
            this._trueSpeed -= dt*g
            if(this._trueSpeed < 0){
                this._trueSpeed = 0
                this._startStop = false
                this.moveToResult()
            }
            this.startWheel(dt*this._trueSpeed)
        }
    },

    async moveToResult(){
        let moveLength = this._resultNode.y - 6
        for (let i = 0; i < this._rollNodeList.length; i++) {
            const element = this._rollNodeList[i];
            cc.tween(element).by(0.2,{y:-moveLength}).start()
        }
        await this.awaitTime(0.2)
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.option)
        this.huoxing.active = false
        this.zhongjiang.active = true
        let actionName = "animation2"
        if(this._resultNode.name === "node3" || this._resultNode.name === "node9" || this._resultNode.name === "node15"){
            actionName = "animation"
        }
        this.zhongjiang.getComponent(sp.Skeleton).setAnimation(0,actionName,true)
        if(this._resultData.jackpot){
            this.node.runAction(cc.shake(0.5,10,10))
            cc.vv.gameData.GetSlotsScript().showWinJackPoolAnimation(this._resultData.jackpot.id)
        }
        await this.awaitTime(0.5)
        this.endSpin()
    },
});
