let speed = 1000
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {

    },

    onDestroy(){

    },

    start () {

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    showRandomAnimation(){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.jili)
            let tempyaList = []
            let posX = [0,-160,-54,53,160];
            let posY = [0,-370,-360,-350,-370];
            for (let i = 1; i <= 4; i++) {
                let yaya = cc.find("ya"+i,this.node)
                let tempyaya = cc.instantiate(yaya)
                tempyaya.parent = yaya.parent
                tempyaya.position = cc.v2(posX[i],posY[i])
                tempyaya.active = true
                tempyaya.getComponent(sp.Skeleton).setAnimation(0,"animation5",false)
                tempyaList.push(tempyaya)
            }
            cc.vv.gameData.GetSlotsScript().showMask(true)
            await this.awaitTime(2.3)
            cc.vv.gameData.GetSlotsScript().showMask(false)
            for (let i = 0; i < tempyaList.length; i++) {
                tempyaList[i].parent = null
            }
            sucess()
        })
    },

    async showYaYa(type,endPosition){
        let yaya = cc.find("ya"+type,this.node)
        if(!yaya.active){
            yaya.active = true
            yaya.getComponent(sp.Skeleton).setAnimation(0,"animation1",true)
            yaya.getComponent(sp.Skeleton).setCompleteListener(null)
            yaya.y = -cc.winSize.height / 2
            if(endPosition){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_rise)
                yaya.x = endPosition.x
                cc.tween(yaya).to(1.5,{y:endPosition.y}).start()
            }else{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_rise)
                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(Global.random(1,5))
                let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                let finalPosition = this.node.convertToNodeSpaceAR(position)
                yaya.x = finalPosition.x
                let finalY = cc.winSize.height / 2
                let endY = yaya.y + 700
                if(cc.vv.gameData.GetSlotsScript()._isInFree){
                    endY = yaya.y + 1060
                    speed = 1500
                }
                cc.tween(yaya).to(1.7,{y:endY}).call(()=>{
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_fly)
                    cc.tween(yaya).to((finalY - yaya.y)/speed,{y:finalY}).call(()=>{
                        yaya.active = false
                    }).start()
                }).start()
            }
        }
    },

    showYaYaResult(bonusGame){
        return new Promise((sucess,failed)=>{
            let type = bonusGame.type
            let effect = bonusGame.effect
            let yaya = cc.find("ya"+type,this.node)
            if(yaya.active){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_open)
                yaya.getComponent(sp.Skeleton).setAnimation(0,"animation2",false)
                yaya.getComponent(sp.Skeleton).addAnimation(0,"animation3",false)
                yaya.getComponent(sp.Skeleton).addAnimation(0,"animation4",false)
                let times = 0
                yaya.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    times++
                    switch (times) {
                        case 1:{  //根据不同的鸭鸭显示不同的效果
                            if(type === 4){
                                this.showEndEffect(type,effect)
                            }
                        }break;
                        case 2:{
                            Global.SlotsSoundMgr.playEffect("random"+type)
                            if(type === 1 || type === 2){
                                this.showEndEffect(type,effect)
                            }else if(type === 3){
                                this.scheduleOnce(()=>{
                                    this.showEndEffect(type,effect,sucess)
                                },0.5)
                            }
                        }break;
                        case 3:{
                            yaya.active = false
                            if(type !== 3){
                                sucess()
                            }
                        }break;
                    }
                })
            }else{
                sucess()
            }
        })
    },

    async showEndEffect(type,effect,_sucess){
        let yaya = cc.find("ya"+type,this.node)
        switch (type) {
            case 1:{//所有字母变wild
                for (let i = 0; i < effect.convertIdxs.length; i++) {
                    const idx = effect.convertIdxs[i];
                    let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                    let _collectNode = cc.vv.gameData.getManage()._collectNode
                    if(symbol){
                        let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                        let finalPosition = _collectNode.convertToNodeSpaceAR(position)
                        let tempNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("zimu"))
                        tempNode.parent = _collectNode
                        tempNode.position = finalPosition
                        if(symbol._id === 9){
                            tempNode.getComponent(sp.Skeleton).setAnimation(0,"animation",false)
                        }else if(symbol._id === 10){
                            tempNode.getComponent(sp.Skeleton).setAnimation(0,"animation2",false)
                        }else if(symbol._id === 11){
                            tempNode.getComponent(sp.Skeleton).setAnimation(0,"animation3",false)
                        }else if(symbol._id === 12){
                            tempNode.getComponent(sp.Skeleton).setAnimation(0,"animation4",false)
                        }
                        tempNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
                            tempNode.parent = null
                        })
                        this.scheduleOnce(()=>{
                            symbol.changeWild()
                        },0.5)
                    }
                }
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild2)
            }break;
            case 2:{  //四周变wild 
                for (let i = 0; i < effect.convertIdxs.length; i++) {
                    const idx = effect.convertIdxs[i];
                    let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                    let _collectNode = cc.vv.gameData.getManage()._collectNode
                    if(symbol){
                        let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                        let finalPosition = _collectNode.convertToNodeSpaceAR(position)
                        let tempNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("zhouwei"))
                        tempNode.parent = _collectNode
                        tempNode.position = finalPosition
                        tempNode.active = true
                        tempNode.getComponent(sp.Skeleton).setAnimation(0,"animation",false)
                        tempNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
                            tempNode.parent = null
                        })
                        this.scheduleOnce(()=>{
                            symbol.changeWild()
                        },0.5)
                    }
                }
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild3)
            }break;
            case 3:{  //倍数转盘
                let position = yaya.convertToWorldSpaceAR(cc.v2(0,0))
                let finalPosition = cc.find("Canvas/safe_node").convertToNodeSpaceAR(position)
                let wheelShow = cc.instantiate(cc.vv.gameData.GetPrefabByName("wheelShow"))
                wheelShow.parent = this.node
                wheelShow.position = this.node.convertToNodeSpaceAR(position)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.smallwheel)
                wheelShow.getComponent(sp.Skeleton).setAnimation(0,"animation",false)
                wheelShow.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    wheelShow.parent = null
                    cc.vv.gameData.getWheelControl().showWheel(finalPosition,effect.mult,_sucess)
                })
            }break;
            case 4:{  //随机位置上变wild
                let position = yaya.convertToWorldSpaceAR(cc.v2(0,0))
                let _collectNode = cc.vv.gameData.getManage()._collectNode
                let startPosition = _collectNode.convertToNodeSpaceAR(position)
                for (let i = 0; i < effect.randIdxs.length; i++) {
                    const idx = effect.randIdxs[i];
                    let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                    let position = symbol.node.convertToWorldSpaceAR(cc.v2(0,0))
                    let finalPosition = _collectNode.convertToNodeSpaceAR(position)
                    let tempNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("qiang2_1"))
                    tempNode.parent = _collectNode
                    tempNode.position = startPosition
                    cc.tween(tempNode).to(0.2,{position:finalPosition}).call(()=>{
                        tempNode.parent = null
                        let shouqiangNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("shouqiang"))
                        shouqiangNode.parent = _collectNode
                        shouqiangNode.position = finalPosition
                        shouqiangNode.getComponent(sp.Skeleton).setAnimation(0,"animation",false)
                        shouqiangNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
                            shouqiangNode.parent = null
                        })
                        this.scheduleOnce(()=>{
                            symbol.changeWild()
                        },0.5)
                    }).start()
                }
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild1)
            }break;
        }
    },

    // update (dt) {},
});
