    setStopWildList(mapInfo){
        if(this._cfg.MapConfig[mapInfo.currId].type < 4){
            return
        }
        if(this._cfg.MapConfig[mapInfo.currId].type == 4){
            this._currWildList = mapInfo.freeInfo.moveWilds.currIdxs || []
        }else if(this._cfg.MapConfig[mapInfo.currId].type == 5){
            this._currWildList = mapInfo.freeInfo.stickyWilds.currIdxs || []
        }
    },

    showMoveWild(mapInfo){
        return new Promise(async (sucess,failed)=>{
            let tempNodeList = []
            for (let i = 0; i < mapInfo.freeInfo.moveWilds.prevIdxs.length; i++) {
                const preidx = mapInfo.freeInfo.moveWilds.prevIdxs[i];
                const curridx = mapInfo.freeInfo.moveWilds.currIdxs[i];
                let position = this.GetSymbolWorldPosByIdx(curridx)
                let finalPosition = this._wildTopNode.convertToNodeSpaceAR(position)
                cc.tween(this._currWildNodeList[preidx]).to(1,{position:finalPosition}).start()
                tempNodeList[curridx] = this._currWildNodeList[preidx]
            }
            this._currWildNodeList = tempNodeList
            this._currWildList = mapInfo.freeInfo.moveWilds.currIdxs || []
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.moving_wild)
            await this.awaitTime(1.2)
            sucess()
        })
    },

